import{describe,it,expect}from"vitest";import fs from"node:fs";import path from"node:path";const IGNORED=new Set([".git","node_modules","dist","coverage"]);function htmlFiles(e,t=[]){for(const o of fs.readdirSync(e,{withFileTypes:!0})){if(IGNORED.has(o.name))continue;const s=path.join(e,o.name);o.isDirectory()?htmlFiles(s,t):o.name.endsWith(".html")&&t.push(s)}return t}const THEME_WRITE=/document\.body\.classList\.add\('light-theme'\)/;describe("theme bootstrap placement",()=>{const e=htmlFiles(".").map(e=>({file:e,content:fs.readFileSync(e,"utf8")}));it("scans the repository",()=>{expect(e.length).toBeGreaterThan(0)}),it("never touches document.body before <body> is parsed",()=>{const t=e.filter(({content:e})=>THEME_WRITE.test(e)).filter(({content:e})=>{const t=e.search(THEME_WRITE),o=e.search(/<body[\s>]/i);return!(o<0)&&(!(t>o)&&!/if\s*\(\s*document\.body\s*\)/.test(e))}).map(({file:e})=>e);expect(t).toEqual([])})});